@@ -0,0 +1,165 @@
+'use client';
+
+import { useCallback } from 'react';
+import axios from 'axios';
+import { toast } from 'sonner';
+import mixpanel from 'mixpanel-browser';
+import { useTranslations } from 'next-intl';
+
+import { startOutpaintImageGeneration } from '@/lib/comfyui';
+import { getRandomSeed } from '@/lib/utils';
+import {
+  convertToBase64,
+  getImageDimensionsFromBase64
+} from '@/utils/client/image';
+import { replaceImage } from '@/utils/client/canvas/image';
+import { useHistoryState } from '@/hooks/use-history-state';
+import { useCanvasGenerationHandler } from '@/hooks/use-canvas-generation-handler';
+import { useSelectionState } from '@/hooks/use-selection-state';
+import useIsBanned from '@/hooks/use-is-banned';
+import type { ExpandOverlayPadding } from '@/store/expand-overlay-store';
+
+import { ImageObject, isImageObject } from '../types';
+import { pollForGeneration } from '../util';
+
+export interface UseExpandFormProps {
+  image: ImageObject | null;
+  padding: ExpandOverlayPadding;
+  onUpdateImage: (image: ImageObject) => void;
+  onSuccess?: () => void;
+}
+
+async function translatePrompt(prompt: string): Promise<string> {
+  try {
+    const response = await axios.post<{ text: string }>('/api/translate', {
+      text: prompt,
+      mode: 'simpleTranslate'
+    });
+    return response.data?.text?.trim() || prompt.trim();
+  } catch {
+    return prompt.trim();
+  }
+}
+
+export function useExpandForm({
+  image,
+  padding,
+  onUpdateImage,
+  onSuccess
+}: UseExpandFormProps) {
+  const tError = useTranslations('errors');
+  const { isBanned, releaseAt } = useIsBanned();
+  const { selection } = useSelectionState();
+  const { commitTempCanvasObjects, canvasObjects } = useHistoryState();
+  const { generateOnCanvas, isGenerating } = useCanvasGenerationHandler();
+
+  const handleGenerate = useCallback(
+    async (prompt: string) => {
+      if (!image || !isImageObject(image) || !prompt.trim()) return;
+      if (isBanned) {
+        toast.error(tError('userBanned', { releaseAt }));
+        return;
+      }
+
+      const translatedPrompt = await translatePrompt(prompt);
+      if (!translatedPrompt) return;
+
+      const targetObject = canvasObjects.find(
+        (obj) => obj.id === selection.selected[0]?.id
+      );
+      const imageSrc = Array.isArray(image.src)
+        ? image.src[image.currentIndex ?? 0]
+        : image.src;
+      const base64Src = await convertToBase64(imageSrc);
+      const seed = getRandomSeed();
+
+      await generateOnCanvas({
+        numberOfImages: 1,
+        objectId: targetObject?.id,
+        action: 'expand',
+        imageObject: image,
+        generationRequest: async () => {
+          const imageGeneration = await startOutpaintImageGeneration({
+            prompt: translatedPrompt,
+            inputImage: base64Src,
+            seed,
+            left: padding.left,
+            top: padding.top,
+            right: padding.right,
+            bottom: padding.bottom,
+            feathering: 24,
+            originalWidth: image.width,
+            originalHeight: image.height
+          });
+
+          return await pollForGeneration({
+            imageGenerationId: imageGeneration.id,
+            requestId: imageGeneration.requestId,
+            baseModel: imageGeneration.baseModel
+          });
+        },
+        onGenerationComplete: async ({
+          imageSrc: resultSrc,
+          imageGenerationId: resultImageGenerationId
+        }) => {
+          if (!resultSrc?.[0]) throw new Error('No image returned');
+          const { width, height } = await getImageDimensionsFromBase64(
+            resultSrc[0]
+          );
+          const scaleX = image.scaleX ?? 1;
+          const scaleY = image.scaleY ?? 1;
+          replaceImage({
+            src: resultSrc,
+            imageGenerationId: resultImageGenerationId,
+            imageObject: {
+              ...image,
+              position: {
+                x: image.position.x - padding.left * scaleX,
+                y: image.position.y - padding.top * scaleY
+              },
+              width,
+              height
+            },
+            onImageLoaded: (newImage) => {
+              onUpdateImage({
+                ...image,
+                position: {
+                  x: image.position.x - padding.left * scaleX,
+                  y: image.position.y - padding.top * scaleY
+                },
+                width,
+                height,
+                src: resultSrc[0],
+                imageGenerationId: resultImageGenerationId
+              });
+              commitTempCanvasObjects({
+                type: 'Expanded Image',
+                objectId: newImage.id
+              });
+              mixpanel.track('[Canvas] Image expanded', { prompt });
+            },
+            userPrompt: prompt,
+            seed
+          });
+          onSuccess?.();
+        },
+        postGenerationCleanup: () => {}
+      });
+    },
+    [
+      image,
+      padding,
+      onUpdateImage,
+      onSuccess,
+      isBanned,
+      releaseAt,
+      tError,
+      canvasObjects,
+      selection.selected,
+      generateOnCanvas,
+      commitTempCanvasObjects
+    ]
+  );
+
+  return { handleGenerate, isGenerating };
+}
