+++ b/components/canvas/expand-overlay-layer.tsx
@@ -0,0 +1,50 @@
+'use client';
+
+import { Rect, Layer } from 'react-konva';
+
+import { useExpandOverlayStore } from '@/store/expand-overlay-store';
+import { useHistoryState } from '@/hooks/use-history-state';
+import { isImageObject } from '@/components/canvas/types';
+
+const BORDER_COLOR = '#3b82f6';
+const BORDER_WIDTH = 2;
+const EXPAND_AREA_COLOR = 'rgba(128, 128, 128, 0.3)';
+
+/**
+ * Renders a semi-transparent rect on the canvas indicating the expand area
+ * when the floating expand panel is open. Subscribes to expand-overlay-store
+ * and canvas objects; draws in canvas coordinates.
+ */
+export function ExpandOverlayLayer() {
+  const { visible, imageId, padding } = useExpandOverlayStore();
+  const { canvasObjects } = useHistoryState();
+
+  if (!visible || !imageId) return null;
+
+  const image = canvasObjects.find(
+    (obj) => obj.id === imageId && isImageObject(obj)
+  );
+  if (!image || !isImageObject(image)) return null;
+
+  const scaleX = image.scaleX ?? 1;
+  const scaleY = image.scaleY ?? 1;
+  const x = image.position.x - padding.left * scaleX;
+  const y = image.position.y - padding.top * scaleY;
+  const width = (image.width + padding.left + padding.right) * scaleX;
+  const height = (image.height + padding.top + padding.bottom) * scaleY;
+
+  return (
+    <Layer listening={false}>
+      <Rect
+        x={x}
+        y={y}
+        width={width}
+        height={height}
+        fill={EXPAND_AREA_COLOR}
+        stroke={BORDER_COLOR}
+        strokeWidth={BORDER_WIDTH}
+        listening={false}
+      />
+    </Layer>
+  );
+}
