@@ -0,0 +1,235 @@
+'use client';
+
+import { useCallback, useRef, useEffect, useState } from 'react';
+
+import { ImageObject, isImageObject } from '@/components/canvas/types';
+import { isPlaceholderImage } from '@/utils/canvas/object';
+import { useFloatingElementPosition } from '@/hooks/use-floating-element-position';
+import { useCanvasTransformStore } from '@/store/canvas-transform-store';
+import { useImageDragStore } from '@/store/image-drag-store';
+import {
+  useExpandOverlayStore,
+  type ExpandOverlayPadding
+} from '@/store/expand-overlay-store';
+import { AspectRatio } from '@/types/image-generation';
+import { ASPECT_RATIO_OPTIONS } from '@/components/common/aspect-ratio-selector';
+import { useExpandForm } from '@/components/canvas/actions-info/use-expand-form';
+
+import { FloatingTextarea } from './FloatingTextarea';
+
+const TEXTAREA_WIDTH = 480;
+const MAX_PIXEL_LIMIT = 4_326_400;
+
+/** Parse AspectRatio enum value (e.g. '1:1', '16:9') to width/height numbers */
+function aspectRatioToWidthHeight(aspectRatio: AspectRatio): {
+  width: number;
+  height: number;
+} {
+  const str = ASPECT_RATIO_OPTIONS[aspectRatio] ?? '1:1';
+  const [w, h] = str.split(':').map(Number);
+  return { width: w, height: h };
+}
+
+function computePaddingFromRatio(
+  imageWidth: number,
+  imageHeight: number,
+  width: number,
+  height: number
+): ExpandOverlayPadding {
+  const targetRatio = width / height;
+  const currentRatio = imageWidth / imageHeight;
+  let newFinalWidth = imageWidth;
+  let newFinalHeight = imageHeight;
+  if (currentRatio > targetRatio) {
+    newFinalHeight = imageWidth / targetRatio;
+  } else {
+    newFinalWidth = imageHeight * targetRatio;
+  }
+  const horizontalExpand = newFinalWidth - imageWidth;
+  const verticalExpand = newFinalHeight - imageHeight;
+  return {
+    left: Math.ceil(horizontalExpand / 2),
+    right: Math.ceil(horizontalExpand / 2),
+    top: Math.ceil(verticalExpand / 2),
+    bottom: Math.ceil(verticalExpand / 2)
+  };
+}
+
+export interface FloatingExpandContainerProps {
+  open: boolean;
+  onClose: () => void;
+  image: ImageObject | null;
+  onUpdateImage: (image: ImageObject) => void;
+}
+
+export function FloatingExpandContainer({
+  open,
+  onClose,
+  image,
+  onUpdateImage
+}: FloatingExpandContainerProps) {
+  const containerRef = useRef<HTMLDivElement>(null);
+  const [prompt, setPrompt] = useState('');
+  const [padding, setPadding] = useState<ExpandOverlayPadding>({
+    left: 0,
+    top: 0,
+    right: 0,
+    bottom: 0
+  });
+  const [selectedAspectRatio, setSelectedAspectRatio] = useState<AspectRatio>(
+    AspectRatio.SQUARE
+  );
+
+  const {
+    open: openOverlay,
+    close: closeOverlay,
+    updatePadding
+  } = useExpandOverlayStore();
+
+  const getTargetObject = useCallback((): ImageObject | undefined => {
+    if (!image || !isImageObject(image)) return undefined;
+    return image;
+  }, [image]);
+
+  const { handleGenerate, isGenerating } = useExpandForm({
+    image,
+    padding,
+    onUpdateImage,
+    onSuccess: onClose
+  });
+
+  const { updatePosition, updatePositionForObject } =
+    useFloatingElementPosition({
+      containerRef,
+      getTargetObject
+    });
+
+  const position = useCanvasTransformStore((state) => state.position);
+  const scale = useCanvasTransformStore((state) => state.scale);
+  const draggingImageId = useImageDragStore((state) => state.draggingImageId);
+  const dragPosition = useImageDragStore((state) => state.dragPosition);
+  const dragDimensions = useImageDragStore((state) => state.dragDimensions);
+  const dragScale = useImageDragStore((state) => state.dragScale);
+
+  const isDraggingThisImage = image && draggingImageId === image.id;
+
+  // When panel opens with an image, init overlay and default to 1:1 ratio
+  useEffect(() => {
+    if (open && image && isImageObject(image)) {
+      const imageWidth = image.width ?? 0;
+      const imageHeight = image.height ?? 0;
+      const { width: rw, height: rh } = aspectRatioToWidthHeight(
+        AspectRatio.SQUARE
+      );
+      const initialPadding =
+        imageWidth > 0 && imageHeight > 0
+          ? computePaddingFromRatio(imageWidth, imageHeight, rw, rh)
+          : { left: 100, top: 100, right: 100, bottom: 100 };
+      setSelectedAspectRatio(AspectRatio.SQUARE);
+      setPadding(initialPadding);
+      openOverlay(image.id, initialPadding);
+    }
+  }, [open, image?.id]); // eslint-disable-line react-hooks/exhaustive-deps -- only when open/image id changes
+
+  // When panel closes, hide overlay
+  useEffect(() => {
+    if (!open) {
+      closeOverlay();
+    }
+  }, [open, closeOverlay]);
+
+  // Sync floating position when panel opens, image changes, or canvas pan/zoom changes
+  useEffect(() => {
+    if (image && open) {
+      updatePosition();
+    }
+  }, [position.x, position.y, scale, image, open, updatePosition]);
+
+  useEffect(() => {
+    if (image && !isDraggingThisImage) {
+      updatePositionForObject(image);
+    }
+  }, [
+    image?.position.x,
+    image?.position.y,
+    image?.width,
+    image?.height,
+    image?.scaleX,
+    image?.scaleY,
+    image,
+    isDraggingThisImage,
+    updatePositionForObject
+  ]);
+
+  useEffect(() => {
+    if (isDraggingThisImage && image && dragPosition && dragDimensions) {
+      const tempImage: ImageObject = {
+        ...image,
+        position: dragPosition,
+        width: dragDimensions.width,
+        height: dragDimensions.height,
+        scaleX: dragScale?.scaleX ?? image.scaleX ?? 1,
+        scaleY: dragScale?.scaleY ?? image.scaleY ?? 1
+      };
+      updatePositionForObject(tempImage);
+    }
+  }, [
+    isDraggingThisImage,
+    dragPosition,
+    dragDimensions,
+    dragScale,
+    image,
+    updatePositionForObject
+  ]);
+
+  const handleAspectRatioChange = useCallback(
+    (aspectRatio: AspectRatio | undefined) => {
+      if (!image || !isImageObject(image) || !aspectRatio) return;
+      setSelectedAspectRatio(aspectRatio);
+      const imageWidth = image.width ?? 0;
+      const imageHeight = image.height ?? 0;
+      const { width: rw, height: rh } = aspectRatioToWidthHeight(aspectRatio);
+      const newPadding = computePaddingFromRatio(
+        imageWidth,
+        imageHeight,
+        rw,
+        rh
+      );
+      setPadding(newPadding);
+      updatePadding(newPadding);
+    },
+    [image, updatePadding]
+  );
+
+  const handleSubmit = useCallback(() => {
+    handleGenerate(prompt);
+  }, [handleGenerate, prompt]);
+
+  const visible = open && !!image && !isPlaceholderImage(image);
+  const imageWidth = image?.width ?? 0;
+  const imageHeight = image?.height ?? 0;
+  const totalPixels =
+    (imageWidth + padding.left + padding.right) *
+    (imageHeight + padding.top + padding.bottom);
+  const isValidDimensions = totalPixels <= MAX_PIXEL_LIMIT;
+  const canSubmit =
+    prompt.trim().length > 0 && isValidDimensions && !isGenerating;
+
+  if (!visible) return null;
+
+  return (
+    <FloatingTextarea
+      ref={containerRef}
+      variant="expand"
+      value={prompt}
+      onChange={setPrompt}
+      onSubmit={handleSubmit}
+      visible={true}
+      width={TEXTAREA_WIDTH}
+      isGenerating={isGenerating}
+      submitDisabled={!canSubmit}
+      selectedAspectRatio={selectedAspectRatio}
+      onAspectRatioChange={handleAspectRatioChange}
+    />
+  );
+}
