diff --git a/store/expand-overlay-store.ts b/store/expand-overlay-store.ts
new file mode 100644
index 0000000..8f3d679
--- /dev/null
+++ b/store/expand-overlay-store.ts
@@ -0,0 +1,43 @@
+import { create } from 'zustand';
+
+export interface ExpandOverlayPadding {
+  left: number;
+  top: number;
+  right: number;
+  bottom: number;
+}
+
+interface ExpandOverlayState {
+  visible: boolean;
+  imageId: string | null;
+  padding: ExpandOverlayPadding;
+  setVisible: (visible: boolean) => void;
+  setImageId: (imageId: string | null) => void;
+  setPadding: (padding: ExpandOverlayPadding) => void;
+  open: (imageId: string, padding: ExpandOverlayPadding) => void;
+  close: () => void;
+  updatePadding: (padding: ExpandOverlayPadding) => void;
+}
+
+const defaultPadding: ExpandOverlayPadding = {
+  left: 0,
+  top: 0,
+  right: 0,
+  bottom: 0
+};
+
+export const useExpandOverlayStore = create<ExpandOverlayState>((set) => ({
+  visible: false,
+  imageId: null,
+  padding: defaultPadding,
+
+  setVisible: (visible) => set({ visible }),
+  setImageId: (imageId) => set({ imageId }),
+  setPadding: (padding) => set({ padding }),
+
+  open: (imageId, padding) => set({ visible: true, imageId, padding }),
+
+  close: () => set({ visible: false, imageId: null, padding: defaultPadding }),
+
+  updatePadding: (padding) => set({ padding })
+}));

